1	/**
2	 * V3 Event Bus System
3	 * Event-driven communication for the 15-agent swarm
4	 *
5	 * Based on ADR-007 (Event Sourcing for State Changes)
6	 */
7	
8	import {
9	  EventType,
10	  EventHandler,
11	  SwarmEvent,
12	  AgentId
13	} from './types.js';
14	
15	// =============================================================================
16	// Event Bus Interface
17	// =============================================================================
18	
19	export interface IEventBus {
20	  subscribe<T>(eventType: EventType, handler: EventHandler<T>): () => void;
21	  subscribeAll(handler: EventHandler): () => void;
22	  emit<T>(event: SwarmEvent<T>): Promise<void>;
23	  emitSync<T>(event: SwarmEvent<T>): void;
24	  getHistory(filter?: EventFilter): SwarmEvent[];
25	  clear(): void;
26	}
27	
28	export interface EventFilter {
29	  types?: EventType[];
30	  sources?: (AgentId | 'swarm')[];
31	  since?: number;
32	  until?: number;
33	  limit?: number;
34	}
35	
36	// =============================================================================
37	// Event Store Interface (Event Sourcing)
38	// =============================================================================
39	
40	export interface IEventStore {
41	  append(event: SwarmEvent): Promise<void>;
42	  getEvents(aggregateId: string, fromVersion?: number): Promise<SwarmEvent[]>;
43	  getAllEvents(filter?: EventFilter): Promise<SwarmEvent[]>;
44	  getSnapshot(aggregateId: string): Promise<EventStoreSnapshot | null>;
45	  saveSnapshot(snapshot: EventStoreSnapshot): Promise<void>;
46	}
47	
48	export interface EventStoreSnapshot {
49	  aggregateId: string;
50	  version: number;
51	  state: unknown;
52	  timestamp: number;
53	}
54	
55	// =============================================================================
56	// Event Bus Implementation
57	// =============================================================================
58	
59	export class EventBus implements IEventBus {
60	  private handlers: Map<EventType | '*', Set<EventHandler>> = new Map();
61	  private history: SwarmEvent[] = [];
62	  private maxHistorySize: number;
63	
64	  constructor(options: { maxHistorySize?: number } = {}) {
65	    this.maxHistorySize = options.maxHistorySize ?? 10000;
66	  }
67	
68	  subscribe<T>(eventType: EventType, handler: EventHandler<T>): () => void {
69	    if (!this.handlers.has(eventType)) {
70	      this.handlers.set(eventType, new Set());
71	    }
